    const customerMarker='picker-'+randomUUID(),customerQuery=base+'/api/admin/requests/customers?search='+encodeURIComponent(customerMarker);
    await db.query("INSERT INTO users(id,email,password_hash,role) SELECT gen_random_uuid()::text,$1||'-'||lpad(n::text,2,'0')||'@example.invalid',password_hash,'customer' FROM users CROSS JOIN generate_series(1,15) n WHERE id=$2",[customerMarker,account.id]);
    const customerFirst=await (await fetch(customerQuery,{headers:adminHeaders})).json();assert.equal(customerFirst.users.length,10);assert.equal(customerFirst.cursorSupported,true);assert.equal(customerFirst.hasMore,true);
    const customerExpected=await (await fetch(customerQuery+'&offset=10',{headers:adminHeaders})).json();await db.query("INSERT INTO users(id,email,password_hash,role) SELECT gen_random_uuid()::text,$1||'-00@example.invalid',password_hash,'customer' FROM users WHERE id=$2",[customerMarker,account.id]);
    const customerNext=await (await fetch(customerQuery+'&before='+encodeURIComponent(customerFirst.nextCursor),{headers:adminHeaders})).json();assert.deepEqual(customerNext.users.map(u=>u.id),customerExpected.users.map(u=>u.id));assert.equal((await fetch(customerQuery+'&before=invalid',{headers:adminHeaders})).status,400);assert.equal((await fetch(customerQuery+'&before='+encodeURIComponent(customerFirst.nextCursor),{headers:accountHeaders})).status,403);
    await db.query("DELETE FROM users WHERE strpos(email,$1)=1",[customerMarker]);
