    const linkedCustomerSearch=base+'/api/admin/requests?search='+encodeURIComponent(accountEmail);assert.ok(!(await (await fetch(linkedCustomerSearch,{headers:adminHeaders})).json()).requests.some(r=>r.id===body.id));assert.equal((await fetch(linkedCustomerSearch,{headers:accountHeaders})).status,403);
    assert.equal((await fetch(customerLink,{method:'POST',headers:adminHeaders,body:JSON.stringify(link)})).status,200);
