test('concurrent identical orders preserve one snapshot and reject conflicting retries', async () => {
 const db=await openDatabase(process.env.PC_LEASE_TEST_DATABASE_URL);try{
  const product=(await db.query('SELECT slug,edit_version FROM products WHERE published=true LIMIT 1')).rows[0];
  const order={id:randomUUID(),companyName:'Example',contactName:'Person',email:'test@example.invalid',phone:'123',lines:[{productSlug:product.slug,productVersion:product.edit_version,mode:'purchase',quantity:1}]};
  const results=await Promise.all(Array.from({length:8},()=>saveMultiQuote(db,order)));
  assert.equal(results.filter(r=>r.created).length,1);
  for(const result of results){assert.equal(result.id,order.id);assert.deepEqual(result.quote,results[0].quote);}
  assert.equal((await db.query('SELECT count(*)::integer AS n FROM requests WHERE id=$1',[order.id])).rows[0].n,1);
  await assert.rejects(saveMultiQuote(db,{...order,lines:[{...order.lines[0],quantity:2}]}),/request_conflict/);
 }finally{await db.end();}
});
